"""Bounded cold-open and eviction checks on the completed private full pack."""
from pathlib import Path
import argparse,json,time
from live_protocol import Channel,ProtocolError,atomic_json,matched_pose,read_json,valid_pose
from launch_session import verify_lease
from live_compare import menu
from measure_session import distribution,sample,settle
from pack_format import sha
def require(ok,why):
 if not ok:raise ProtocolError(why)
def main():
 p=argparse.ArgumentParser();p.add_argument('--session',type=Path,required=True);p.add_argument('--reserved-window',required=True);p.add_argument('--stage',choices=['cold','eviction'],required=True);a=p.parse_args();w=Path(__file__).resolve().parents[2]/'.local/atlas2';s=a.session.resolve();s.relative_to(w.resolve());pack=w/'parity-full16';state=read_json(pack/'generation-state.json');verified=read_json(w/'full-pack-validation.json');require(state.get('state')=='complete' and state.get('complete_views')==602,'All 602 generated views are required');require(verified.get('pass') and verified.get('improved_views')==602 and verified.get('index_sha256')==sha(pack/'atlas2-index.json'),'Full offline validation identity is required');config=read_json(w/'Atlas2-test/atlas2-local.json');require(Path(config['directory']).resolve()==pack.resolve(),'Private install points at a different pack');verify_lease(w,a.reserved_window);c=Channel(s/'map-qa/trace.json.atlas2.json',w/'Atlas2-test/bin/bb-probe.exe',max_age=30);initial=c.read();require(initial.get('measurement',{}).get('enabled') and valid_pose(initial.get('pose')),'Loaded pose and opt-in native counters required');menu(c,c.trace.parent/'pad.txt');pose=c.read()['pose'];rows=[]
 if a.stage=='cold':
  before=c.read();require(not before['area_loaded'] and before['resident_slots']==0 and not before['open'],'Fresh-process first map use required; refusing a false cold measurement');started=time.monotonic();issued=c.command('atlas2-measure-open-static full_static_cold');generation=issued['ack']['measurement_generation'];ready=c.rendered(0,issued['sequence'],timeout=60);ready_seconds=time.monotonic()-started;require(ready['detail_ppu']==16 and ready['composite'] and ready['prepared_external_views']==1,'Improved lazy view was not rendered');require(matched_pose(pose,ready['pose']),'Pose changed during cold opening');settle(c,5,pose);stopped=c.command('atlas2-measure-stop');native=read_json(c.trace.parent/'trace.json.measurement.json');require(native.get('generation')==generation and not native.get('overflow'),'Cold native sample mismatch');atomic_json(s/'full-static-cold-native.json',native);cpu=distribution(native['map_cpu_elapsed_ms']);cpu.pop('fps_from_interval_mean',None);rows.append(dict(condition='static_first_open',first_ready_hook_seconds=ready_seconds,readiness_scope='Correlated control write/ack through complete visible-tile telemetry; includes polling, not exact button-to-photon latency',cold_definition='First map use and empty tile cache in this process; OS file/shader caches may be warm',before=before,ready=ready,after=stopped,setup_cpu_elapsed_ms=native['setup_cpu_elapsed_ms'],first_map_cpu_ms=native['map_cpu_elapsed_ms'][0] if native['map_cpu_elapsed_ms'] else None,present=distribution(native['present_interval_ms']),map_cpu=cpu))
  for condition in ['static_warm_a','static_closed','ui_disabled','static_warm_b']:
   rows.append(sample(c,s,condition,6,pose));atomic_json(s/'full-cold-open-checks.json',dict(schema=1,complete=False,results=rows,pose=pose))
  rows.append(sample(c,s,'reference_cold',5,pose,cold=True));atomic_json(s/'full-cold-open-checks.json',dict(schema=1,complete=True,results=rows,pose=pose,images_uploaded=False,all_area_performance_claimed=False));c.command('enable');c.command('atlas2-static');c.command('close');print('FULL_NATIVE_COLD_OPEN_COMPLETE conditions='+str(len(rows)));return
 c.command('enable');c.command('open');c.command('atlas2-static');issued=c.command('recenter');start=c.rendered(0,issued['sequence']);area=start['render']['area'];m=read_json(pack/area/'manifest.json');strict=start['render']['strict_layer'];n=len(m['views']);selected=sorted(set([strict]+list(range(0,n,max(1,n//8)))));initial_created=start.get('texture_creations_total',0);initial_evicted=start.get('evictions_total',0);peak_slots=peak_retired=peak_uploads=0;max_prepared=0;deadline=time.monotonic()+180
 try:
  for layer in selected+[strict]:
   require(time.monotonic()<deadline,'Eviction test time bound');issued=c.command('atlas2-floor '+str(layer));after=issued['sequence'];samples=0
   while True:
    observed=c.wait(lambda x:True,after=after,timeout=30);after=observed['sequence'];samples+=1;require(matched_pose(pose,observed['pose']),'Pose changed during manual view cycle');require(observed['resident_slots']<=64 and observed['uploads_this_frame']<=4,'Cache/upload bound');require(observed['backend_owned_slots']==observed['distinct_owned_backend_ids'],'Backend ownership identity collision');require(observed['prepared_external_views']<=1,'More than one external floor detail retained');require(observed['integrity_failures']==0,'Pack integrity failure');peak_slots=max(peak_slots,observed['resident_slots']);peak_retired=max(peak_retired,observed['retiring_slots']);peak_uploads=max(peak_uploads,observed['uploads_this_frame']);max_prepared=max(max_prepared,observed['prepared_external_views']);r=observed.get('render',{})
    if r.get('layer')==layer and r.get('mode')==0 and observed['backend_ready_tiles']==observed['visible_tiles'] and observed['uploads_this_frame']==0:break
    require(time.monotonic()<deadline,'Eviction warmup bound')
   rows.append(dict(layer=layer,polls=samples,stats=observed));atomic_json(s/'full-eviction-checks.json',dict(schema=1,complete=False,results=rows))
  final=c.read();require(final['evictions_total']>initial_evicted and final['texture_creations_total']-initial_created>64,'Test did not actually force eviction/reload');c.command('atlas2-floor-auto');issued=c.command('recenter');restored=c.rendered(0,issued['sequence']);require(restored['render']['layer']==restored['render']['strict_layer']==strict,'Automatic floor not restored');atomic_json(s/'full-eviction-checks.json',dict(schema=1,complete=True,results=rows,peak_slots=peak_slots,peak_retiring=peak_retired,peak_uploads=peak_uploads,max_prepared_external_views=max_prepared,texture_creations_delta=final['texture_creations_total']-initial_created,evictions_delta=final['evictions_total']-initial_evicted,auto_floor_restored=True,finite_sample=True,images_uploaded=False));print('FULL_NATIVE_EVICTION_PASS layers='+str(len(rows))+' slots='+str(peak_slots))
 finally:c.command('atlas2-floor-auto');c.command('atlas2-static');c.command('close')
if __name__=='__main__':main()
